import Vue from 'vue'

import VueRouter from 'vue-router'
// import HM from '../views/example3/HomeView.vue'
// import NotFound from '../views/example3/NotFound.vue' 
// import UserLogin from '../views/example3/UserLogin.vue'


Vue.use(VueRouter)

const routes = [
  {
    path: '/',
    name: 'home',
    redirect:'/m4',
    component: ()=> import('../views/example5/HomeView.vue'),

  },
  {
    path: '/404',
    name: 'notfound',
    redirect:'/login',
    component: () => import('../views/example5/NotFound.vue')
  },
  {
    path: '/login',
    name: 'login',
    component: () => import('../views/example5/UserLogin.vue')
  },
  {
    path: '*',
    redirect: '/404'
  }
]

const router = new VueRouter({
  routes
})

//判断会话中是否有存储的路由信息
const serveRoutes = sessionStorage.getItem('serveRoutes');
if(serveRoutes){
  const array = JSON.parse(serveRoutes);
  addserveroutes(array);
}


// 重重路由
export function resetrouter(){
  router.matcher = new VueRouter({
    routes
  }).matcher
}

export function addserveroutes(array){

  console.log(router.getRoutes());
  for(const{id,path,component} of array){
   // console.log(id,path,component);
   if(component!==null){
       router.addRoute('home',{
           path: path,
           name: id,
           component: () => import(`@/views/example5/container/${component}`)
       })
   }
  }
  console.log(router.getRoutes());
}

export default router
